use c6_core::{core_player::{initialization::{self as init,capture::*}},core_stream::{ThroughRandom,ThroughRandomError},map,unit};
use sha2::{Digest,Sha256};use serde_json::{Value,json};use std::{collections::{BTreeMap,BTreeSet},path::Path};
fn digest(b:&[u8])->[u8;32]{Sha256::digest(b).into()}
fn hex(b:&[u8])->String{b.iter().map(|x|format!("{x:02x}")).collect()}
fn main(){let arg=std::env::args().nth(1).unwrap();let m:Value=serde_json::from_slice(&std::fs::read(&arg).unwrap()).unwrap();let base=Path::new(&arg).parent().unwrap();let mut bytes=BTreeMap::new();for k in ["observations_jsonl","runtime_plan_json","static_plan_json","prepared_report_json","exit_json","target_module","target_host","input_save","input_core"]{bytes.insert(k,std::fs::read(base.join(m[k].as_str().unwrap())).unwrap());}
let load=|key:&str|->BTreeMap<String,Vec<u8>>{m[key].as_object().unwrap().iter().map(|(k,v)|(k.clone(),std::fs::read(base.join(v.as_str().unwrap())).unwrap())).collect()};let outputs=load("outputs");let sources=load("source_files");
let named_outputs:Vec<_>=outputs.iter().map(|(name,bytes)|NamedArtifact{name,bytes}).collect();let named_sources:Vec<_>=sources.iter().map(|(name,bytes)|NamedArtifact{name,bytes}).collect();
let capture=admit_capture(CaptureArtifacts{observations_jsonl:&bytes["observations_jsonl"],runtime_plan_json:&bytes["runtime_plan_json"],static_plan_json:&bytes["static_plan_json"],prepared_report_json:&bytes["prepared_report_json"],exit_json:&bytes["exit_json"],target_module:&bytes["target_module"],target_host:&bytes["target_host"],input_save:&bytes["input_save"],input_core:&bytes["input_core"],outputs:&named_outputs,source_files:&named_sources},CaptureLimits::default()).unwrap();assert!(!capture.native_acceptance());assert_eq!(capture.snapshots().len(),129);
let mut bindings=vec![];for s in capture.snapshots(){let role=s.captured_role().unwrap();assert_eq!(role.capture.raw_observation_sha256,digest(&bytes["observations_jsonl"]));assert!(!s.initialization_reconstructed());if !bindings.contains(&role.binding){bindings.push(role.binding.clone());}}
assert_eq!(bindings.len(),3);let shared=map::Limits{max_bytes:256*1024*1024,max_items:64*1024*1024,..map::Limits::default()};let limit=unit::Limits{max_bytes:128*1024*1024,max_items:64*1024*1024};let mut seen=BTreeSet::new();let mut results=vec![];
for binding in bindings{
let raw=match binding.role{init::WireRole::ReadInputCore=>&bytes["input_core"],init::WireRole::SavedOutputCore=>outputs.get(std::str::from_utf8(binding.output_id.as_ref().unwrap()).unwrap()).unwrap()};assert_eq!(digest(raw),binding.core_sha256);let provider=capture.for_binding(&binding);let p=ThroughRandom::decode(raw,shared,limit,binding.clone(),&provider).unwrap();assert_eq!(p.global_ai.consumed,70934595);assert_eq!(p.consumed,71027796);assert_eq!(p.items_used,10678503);assert!(p.global_ai.players.player_prefix.complete_player_manager_wire());assert_eq!(p.barbarian.instances.len(),197);assert_eq!(p.free_cities.instances.len(),55);assert_eq!(p.tail,&raw[p.consumed..]);assert!(std::ptr::eq(p.tail.as_ptr(),raw[p.consumed..].as_ptr()));
let parts=[p.barbarian.encode_with_items(limit).unwrap(),p.free_cities.encode_with_items(limit).unwrap(),p.random.encode_with_items(limit).unwrap()];let mut cursor=p.global_ai.consumed;let mut items=p.global_ai.items_used;let mut ranges=vec![];for (wire,charge)in &parts{assert_eq!(wire,&raw[cursor..cursor+wire.len()]);ranges.push(json!({"start":cursor,"end":cursor+wire.len(),"items":charge,"sha256":hex(&digest(wire))}));cursor+=wire.len();items+=charge;}assert_eq!(cursor,p.consumed);assert_eq!(items,p.items_used);assert_eq!(parts[2].1,0);let random_start=p.consumed-18;let rw=&raw[random_start..p.consumed];let word=|i|u32::from_le_bytes(rw[i..i+4].try_into().unwrap());assert_eq!(word(0),1);assert_eq!(rw[17],0);assert_eq!(p.random.record.seed,word(4));assert_eq!(p.random.record.calls,word(8));assert_eq!(p.random.record.resets,word(12));assert_eq!(p.random.record.synchronous_byte,rw[16]);assert_eq!(p.random.encode_with_items(unit::Limits{max_bytes:18,max_items:0}).unwrap(),(rw.to_vec(),0));
let caps=seen.insert(binding.core_sha256);if caps{let exact=map::Limits{max_bytes:p.consumed,max_items:p.items_used,max_allocation:p.global_ai.players.core.logical_allocation_used,..shared};let post=unit::Limits{max_bytes:p.consumed-p.global_ai.players.core.map_end,max_items:p.items_used-p.global_ai.players.core.items_used};assert!(ThroughRandom::decode(raw,exact,post,binding.clone(),&provider).is_ok());
for(short_shared,short_post)in[(map::Limits{max_bytes:exact.max_bytes-1,..exact},post),(exact,unit::Limits{max_bytes:post.max_bytes-1,..post})]{assert!(matches!(ThroughRandom::decode(raw,short_shared,short_post,binding.clone(),&provider),Err(ThroughRandomError::Random(c6_core::game_random_wire::Error::ResourceLimit))));}
for(short_shared,short_post)in[(map::Limits{max_items:exact.max_items-1,..exact},post),(exact,unit::Limits{max_items:post.max_items-1,..post})]{assert!(ThroughRandom::decode(raw,short_shared,short_post,binding.clone(),&provider).is_err());}}
results.push(json!({"role":format!("{:?}",binding.role),"core_sha256":hex(&binding.core_sha256),"stream_occurrence":std::str::from_utf8(&binding.occurrence_id).unwrap(),"output_id":binding.output_id.as_ref().map(|b|std::str::from_utf8(b).unwrap()),"global_ai_end":p.global_ai.consumed,"consumed":p.consumed,"items":p.items_used,"new_owners":ranges,"barbarian_instances":p.barbarian.instances.len(),"free_cities_instances":p.free_cities.instances.len(),"random":{"seed":word(4),"calls":word(8),"resets":word(12),"synchronous_byte":rw[16]},"tail_sha256":hex(&digest(p.tail)),"tail_bytes":p.tail.len(),"exact_one_short_caps_tested":caps}));}
println!("{}",json!({"schema":"independent-through-random-review-v1","candidate_sha256":hex(&digest(&std::fs::read(std::env::current_exe().unwrap()).unwrap())),"roles":results,"original_execution":false,"full_rng_inventory":false,"rng_transition_parity":false,"world_import":false}));}
